mapper.select:
select o.*
from orders o


        and o.number = #{dto.number}


        and o.phone like concat('%', #{dto.phone}, '%')


        and o.status = #{dto.status}


        and o.order_time >= #{dto.beginTime}


        and o.order_time <= #{dto.endTime}


        and o.user_id = #{dto.userId}


order by o.order_time desc

mapper.update:
update orders
status = #{status}, cancel_reason = #{cancelReason}, cancel_time = #{cancelTime}, rejection_reason = #{rejectionReason}, delivery_time = #{deliveryTime}, checkout_time = #{checkoutTime},
where id = #{id}
